mapper.delete:
DELETE tm FROM trade_matches tm
JOIN trades t ON t.trade_id = tm.buy_trade_id
WHERE tm.security_id = #{securityId}
  AND t.account_id = #{accountId}

DELETE tm FROM trade_matches tm
JOIN trades t ON t.trade_id = tm.buy_trade_id
WHERE t.account_id = #{accountId}

mapper.select:
SELECT tm.holding_days FROM trade_matches tm JOIN trades t ON t.trade_id = tm.buy_trade_id JOIN trades sell_t ON sell_t.trade_id = tm.sell_trade_id WHERE t.account_id IN
#{accountId}
AND sell_t.traded_at >= #{since}
